def process_orders(orders):
    total = 0.0
    failed = []
    for item in orders:
        try:
            a = item.get('amount')
            q = item.get('quantity')
            if a is None or q is None:
                failed.append(item.get('id') if hasattr(item, 'get') else None)
                continue
            total += float(a) * float(q)
        except Exception:
            failed.append(item.get('id') if hasattr(item, 'get') else None)
    return {'revenue': total, 'failed_orders': failed}
